$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "if\(slk&&pxIsSet\(slk\.clothes\)\)\{"
$r1="if(slk){   // v28.xx (cw-pixmelee) I3: a plain look keeps its pixel body in a swing or punch too (was: only the three full sets); the hand is the skin ramp"
$a2=L "hand=lk\.clothes==='skeleton'\?PXS_BONE\[1\]:\(lk\.clothes==='trooper'\?PXS_DARK\[1\]:PXS_PALE\[1\]\);"
$r2="hand=lk.clothes==='skeleton'?PXS_BONE[1]:(lk.clothes==='trooper'?PXS_DARK[1]:(lk.clothes==='android'?PXS_PALE[1]:(lk.bot===2?PXB_GOLD.skin[1]:(PIXRAMPS.skins[lk.skin]||PIXRAMPS.skins.fair)[1])));   // v28.xx (cw-pixmelee) I3: plain looks use the skin ramp"
$a3=L "var fam='setmelee\|'\+lk\.clothes\+'\|'\+\(crow\?1:0\),sp="
$r3="var fam='setmelee|'+lk.clothes+'|'+hand+'|'+(crow?1:0),sp="
$chk=@'
  {v:'VER',what:'a crowbar swing or punch keeps the pixel body on a plain look (no flip to the vector art)',
   run:function(){
     if(typeof pixDrawOp!=='function'||typeof pxLookOf!=='function') return 'SKIP: no pixel painter';
     var st=null,b0,i,bad=[],ok;
     try{ st=(typeof opState==='function')?opState(P&&P.hero||null):null; }catch(e){ st=null; }
     if(!st&&typeof __pxHeroState==='function') st=__pxHeroState();
     if(!st||!st.own) return 'SKIP: no hero draw state';
     var sv=P.cosOutfit; P.cosOutfit='outnone';
     try{
       var lk=pxLookOf(st); if(!lk||pxIsSet(lk.clothes)) return 'SKIP: the hero is not a plain look';
       ['fist'].forEach(function(md){
         G.punchT=0.1; G.barT=0;
         wc.save(); wc.setTransform(1,0,0,1,0,0);
         try{ b0=PIX.bodies; for(i=0;i<4;i++){ pixFrame(); ok=pixDrawOp(600,500,0,0,'#242832',0,0,md,0,st); } if(!ok||PIX.bodies===b0) bad.push('a punch on a plain look was not drawn in pixels');
           G.punchT=0; G.barT=0.1; b0=PIX.bodies; for(i=0;i<4;i++){ pixFrame(); ok=pixDrawOp(600,500,0,0,'#242832',0,0,md,0,st); } if(!ok||PIX.bodies===b0) bad.push('a crowbar swing on a plain look was not drawn in pixels');
         }finally{ wc.restore(); G.punchT=0; G.barT=0; }
       });
     }finally{ P.cosOutfit=sv; }
     return bad.length?bad.join('; '):null; }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='PIXEL BODY KEEPS ITS SWING'
  why='Idea I3 of the graphics list. A crowbar swing or punch flipped a plain-look pillager into the old vector art for 0.22 s. The pixel body now stays and swings the pixel crowbar or fist, as the three full sets already do. Hand colour is the skin ramp. Same arc timing on barT and punchT.'
  now='A crowbar swing or punch keeps the pixel body on every look.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 }, [ordered]@{ anchor=$a2; replacement=$r2 }, [ordered]@{ anchor=$a3; replacement=$r3 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-pixmelee.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
